1	package handler
2	
3	import (
4		"context"
5		"fmt"
6		"io"
7		"log/slog"
8		"os"
9		"path/filepath"
10		"regexp"
11		"sort"
12		"strings"
13		"time"
14	
15		"github.com/modelcontextprotocol/go-sdk/mcp"
16		"github.com/nsega/mcp-obsidian/internal/note"
17		"github.com/nsega/mcp-obsidian/internal/vault"
18	)
19	
20	// Handler holds the vault reference and provides MCP tool handler methods
21	type Handler struct {
22		vault  *vault.Vault
23		logger *slog.Logger
24	}
25	
26	// New creates a new Handler with the given Vault and Logger
27	func New(v *vault.Vault, logger *slog.Logger) *Handler {
28		if logger == nil {
29			logger = slog.New(slog.NewTextHandler(io.Discard, nil))
30		}
31		return &Handler{vault: v, logger: logger}
32	}
33	
34	// SearchNotes implements the search_notes tool
35	func (h *Handler) SearchNotes(ctx context.Context, req *mcp.CallToolRequest, input note.SearchNotesInput) (*mcp.CallToolResult, note.SearchNotesOutput, error) {
36		var results []string
37		query := input.Query
38	
39		// Use case-insensitive literal matching via regexp.QuoteMeta to prevent
40		// regex injection from user-provided queries
41		re := regexp.MustCompile("(?i)" + regexp.QuoteMeta(query))
42	
43		// Walk through the vault directory
44		err := filepath.Walk(h.vault.Path, func(path string, info os.FileInfo, err error) error {
45			if ctx.Err() != nil {
46				return ctx.Err()
47			}
48	
49			if err != nil {
50				h.logger.Debug("skipping path", "path", path, "error", err)
51				return nil
52			}
53	
54			// Skip directories
55			if info.IsDir() {
56				// Check if directory is allowed (not hidden)
57				allowed, checkErr := h.vault.IsPathAllowed(path)
58				if checkErr != nil || !allowed {
59					return filepath.SkipDir
60				}
61				return nil
62			}
63	
64			// Only process markdown files
65			if !strings.HasSuffix(strings.ToLower(path), ".md") {
66				return nil
67			}
68	
69			// Check if file is allowed
70			allowed, checkErr := h.vault.IsPathAllowed(path)
71			if checkErr != nil || !allowed {
72				return nil
73			}
74	
75			// Get filename
76			filename := filepath.Base(path)
77	
78			if re.MatchString(filename) {
79				results = append(results, path)
80				// Limit results
81				if len(results) >= vault.MaxSearchResults {
82					return filepath.SkipAll
83				}
84			}
85	
86			return nil
87		})
88	
89		if err != nil {
90			return nil, note.SearchNotesOutput{}, fmt.Errorf("failed to search notes: %w", err)
91		}
92	
93		output := note.SearchNotesOutput{
94			Results: results,
95		}
96	
97		// Create text content for the result
98		textContent := fmt.Sprintf("Found %d matching notes", len(results))
99		if len(results) > 0 {
100			textContent += ":\n" + strings.Join(results, "\n")
101		}
102	
103		result := &mcp.CallToolResult{
104			Content: []mcp.Content{
105				&mcp.TextContent{
106					Text: textContent,
107				},
108			},
109		}
110	
111		return result, output, nil
112	}
113	
114	// ReadNotes implements the read_notes tool
115	func (h *Handler) ReadNotes(ctx context.Context, req *mcp.CallToolRequest, input note.ReadNotesInput) (*mcp.CallToolResult, note.ReadNotesOutput, error) {
116		if len(input.Paths) > vault.MaxReadPaths {
117			return nil, note.ReadNotesOutput{}, fmt.Errorf("too many paths: %d exceeds limit of %d", len(input.Paths), vault.MaxReadPaths)
118		}
119	
120		notes := make([]note.NoteContent, 0, len(input.Paths))
121	
122		for _, path := range input.Paths {
123			n := note.NoteContent{
124				Path: path,
125			}
126	
127			// Check if path is allowed
128			allowed, err := h.vault.IsPathAllowed(path)
129			if err != nil {
130				n.Error = fmt.Sprintf("Path validation error: %v", err)
131				notes = append(notes, n)
132				continue
133			}
134	
135			if !allowed {
136				n.Error = "Access denied: path is outside vault or is a hidden file"
137				notes = append(notes, n)
138				continue
139			}
140	
141			// Read file content
142			content, err := os.ReadFile(path)
143			if err != nil {
144				n.Error = fmt.Sprintf("Failed to read file: %v", err)
145				notes = append(notes, n)
146				continue
147			}
148	
149			n.Content = string(content)
150			notes = append(notes, n)
151		}
152	
153		output := note.ReadNotesOutput{
154			Notes: notes,
155		}
156	
157		// Create text content for the result
158		var textParts []string
159		for _, n := range notes {
160			if n.Error != "" {
161				textParts = append(textParts, fmt.Sprintf("## %s\nError: %s", n.Path, n.Error))
162			} else {
163				textParts = append(textParts, fmt.Sprintf("## %s\n%s", n.Path, n.Content))
164			}
165		}
166	
167		result := &mcp.CallToolResult{
168			Content: []mcp.Content{
169				&mcp.TextContent{
170					Text: strings.Join(textParts, "\n\n"),
171				},
172			},
173		}
174	
175		return result, output, nil
176	}
177	
178	// CreateNote implements the create_note tool
179	func (h *Handler) CreateNote(ctx context.Context, req *mcp.CallToolRequest, input note.CreateNoteInput) (*mcp.CallToolResult, note.CreateNoteOutput, error) {
180		if input.Title == "" {
181			return nil, note.CreateNoteOutput{}, fmt.Errorf("title is required")
182		}
183	
184		if len(input.Content) > vault.MaxContentSize {
185			return nil, note.CreateNoteOutput{}, fmt.Errorf("content too large: %d bytes exceeds limit of %d", len(input.Content), vault.MaxContentSize)
186		}
187	
188		slug := note.Slugify(input.Title)
189		if slug == "" {
190			return nil, note.CreateNoteOutput{}, fmt.Errorf("title produces an empty slug")
191		}
192	
193		today := time.Now().Format("2006-01-02")
194		filename := today + "_" + slug + ".md"
195	
196		dir := h.vault.Path
197		if input.Folder != "" {
198			dir = filepath.Join(h.vault.Path, input.Folder)
199		}
200	
201		fullPath := filepath.Join(dir, filename)
202	
203		allowed, err := h.vault.IsPathAllowed(fullPath)
204		if err != nil {
205			return nil, note.CreateNoteOutput{}, fmt.Errorf("path validation error: %w", err)
206		}
207		if !allowed {
208			return nil, note.CreateNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
209		}
210	
211		if err = os.MkdirAll(dir, 0755); err != nil {
212			return nil, note.CreateNoteOutput{}, fmt.Errorf("failed to create directory: %w", err)
213		}
214	
215		frontmatter := note.GenerateFrontmatter(input.Tags, today, today)
216	
217		var content strings.Builder
218		content.WriteString(frontmatter)
219		content.WriteString("\n# ")
220		content.WriteString(input.Title)
221		content.WriteByte('\n')
222		if input.Content != "" {
223			content.WriteByte('\n')
224			content.WriteString(input.Content)
225			content.WriteByte('\n')
226		}
227	
228		// Use O_CREATE|O_EXCL to atomically fail if file already exists (prevents TOCTOU)
229		f, err := os.OpenFile(fullPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0644)
230		if err != nil {
231			if os.IsExist(err) {
232				return nil, note.CreateNoteOutput{}, fmt.Errorf("file already exists: %s", fullPath)
233			}
234			return nil, note.CreateNoteOutput{}, fmt.Errorf("failed to create file: %w", err)
235		}
236		_, writeErr := f.WriteString(content.String())
237		closeErr := f.Close()
238		if writeErr != nil {
239			return nil, note.CreateNoteOutput{}, fmt.Errorf("failed to write file: %w", writeErr)
240		}
241		if closeErr != nil {
242			return nil, note.CreateNoteOutput{}, fmt.Errorf("failed to close file: %w", closeErr)
243		}
244	
245		output := note.CreateNoteOutput{Path: fullPath}
246		result := &mcp.CallToolResult{
247			Content: []mcp.Content{
248				&mcp.TextContent{Text: fmt.Sprintf("Created note: %s", fullPath)},
249			},
250		}
251		return result, output, nil
252	}
253	
254	// UpdateNote implements the update_note tool
255	func (h *Handler) UpdateNote(ctx context.Context, req *mcp.CallToolRequest, input note.UpdateNoteInput) (*mcp.CallToolResult, note.UpdateNoteOutput, error) {
256		if len(input.Content) > vault.MaxContentSize {
257			return nil, note.UpdateNoteOutput{}, fmt.Errorf("content too large: %d bytes exceeds limit of %d", len(input.Content), vault.MaxContentSize)
258		}
259	
260		allowed, err := h.vault.IsPathAllowed(input.Path)
261		if err != nil {
262			return nil, note.UpdateNoteOutput{}, fmt.Errorf("path validation error: %w", err)
263		}
264		if !allowed {
265			return nil, note.UpdateNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
266		}
267	
268		if _, err := os.Stat(input.Path); os.IsNotExist(err) {
269			return nil, note.UpdateNoteOutput{}, fmt.Errorf("file does not exist: %s", input.Path)
270		} else if err != nil {
271			return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to stat file: %w", err)
272		}
273	
274		mode := input.Mode
275		if mode == "" {
276			mode = "replace"
277		}
278	
279		switch mode {
280		case "replace":
281			if err := os.WriteFile(input.Path, []byte(input.Content), 0644); err != nil {
282				return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
283			}
284		case "append":
285			f, err := os.OpenFile(input.Path, os.O_WRONLY|os.O_APPEND, 0644)
286			if err != nil {
287				return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to open file for append: %w", err)
288			}
289			_, writeErr := f.WriteString("\n\n" + input.Content)
290			closeErr := f.Close()
291			if writeErr != nil {
292				return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to append to file: %w", writeErr)
293			}
294			if closeErr != nil {
295				return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to close file: %w", closeErr)
296			}
297		default:
298			return nil, note.UpdateNoteOutput{}, fmt.Errorf("invalid mode: %s (must be 'replace' or 'append')", mode)
299		}
300	
301		output := note.UpdateNoteOutput{Path: input.Path}
302		result := &mcp.CallToolResult{
303			Content: []mcp.Content{
304				&mcp.TextContent{Text: fmt.Sprintf("Updated note (%s): %s", mode, input.Path)},
305			},
306		}
307		return result, output, nil
308	}
309	
310	// DeleteNote implements the delete_note tool
311	func (h *Handler) DeleteNote(ctx context.Context, req *mcp.CallToolRequest, input note.DeleteNoteInput) (*mcp.CallToolResult, note.DeleteNoteOutput, error) {
312		if !strings.HasSuffix(strings.ToLower(input.Path), ".md") {
313			return nil, note.DeleteNoteOutput{}, fmt.Errorf("can only delete .md files")
314		}
315	
316		allowed, err := h.vault.IsPathAllowed(input.Path)
317		if err != nil {
318			return nil, note.DeleteNoteOutput{}, fmt.Errorf("path validation error: %w", err)
319		}
320		if !allowed {
321			return nil, note.DeleteNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
322		}
323	
324		info, err := os.Stat(input.Path)
325		if os.IsNotExist(err) {
326			return nil, note.DeleteNoteOutput{}, fmt.Errorf("file does not exist: %s", input.Path)
327		}
328		if err != nil {
329			return nil, note.DeleteNoteOutput{}, fmt.Errorf("failed to stat file: %w", err)
330		}
331		if info.IsDir() {
332			return nil, note.DeleteNoteOutput{}, fmt.Errorf("cannot delete directories")
333		}
334	
335		if err := os.Remove(input.Path); err != nil {
336			return nil, note.DeleteNoteOutput{}, fmt.Errorf("failed to delete file: %w", err)
337		}
338	
339		output := note.DeleteNoteOutput(input)
340		result := &mcp.CallToolResult{
341			Content: []mcp.Content{
342				&mcp.TextContent{Text: fmt.Sprintf("Deleted note: %s", input.Path)},
343			},
344		}
345		return result, output, nil
346	}
347	
348	// SearchContent implements the search_content tool
349	func (h *Handler) SearchContent(ctx context.Context, req *mcp.CallToolRequest, input note.SearchContentInput) (*mcp.CallToolResult, note.SearchContentOutput, error) {
350		query := input.Query
351	
352		// Use case-insensitive literal matching via regexp.QuoteMeta to prevent
353		// regex injection from user-provided queries
354		re := regexp.MustCompile("(?i)" + regexp.QuoteMeta(query))
355	
356		var results []note.ContentMatch
357	
358		err := filepath.Walk(h.vault.Path, func(path string, info os.FileInfo, err error) error {
359			if ctx.Err() != nil {
360				return ctx.Err()
361			}
362	
363			if err != nil {
364				h.logger.Debug("skipping path", "path", path, "error", err)
365				return nil
366			}
367	
368			if info.IsDir() {
369				allowed, checkErr := h.vault.IsPathAllowed(path)
370				if checkErr != nil || !allowed {
371					return filepath.SkipDir
372				}
373				return nil
374			}
375	
376			if !strings.HasSuffix(strings.ToLower(path), ".md") {
377				return nil
378			}
379	
380			allowed, checkErr := h.vault.IsPathAllowed(path)
381			if checkErr != nil || !allowed {
382				return nil
383			}
384	
385			data, err := os.ReadFile(path)
386			if err != nil {
387				h.logger.Debug("skipping unreadable file", "path", path, "error", err)
388				return nil
389			}
390	
391			lines := strings.Split(string(data), "\n")
392			for lineNum, line := range lines {
393	
394				if re.MatchString(line) {
395					results = append(results, note.ContentMatch{
396						Path:    path,
397						Snippet: line,
398						Line:    lineNum + 1,
399					})
400					if len(results) >= vault.MaxSearchResults {
401						return filepath.SkipAll
402					}
403				}
404			}
405	
406			return nil
407		})
408	
409		if err != nil {
410			return nil, note.SearchContentOutput{}, fmt.Errorf("failed to search content: %w", err)
411		}
412	
413		output := note.SearchContentOutput{Results: results}
414	
415		textContent := fmt.Sprintf("Found %d matching lines", len(results))
416		if len(results) > 0 {
417			var lines []string
418			for _, m := range results {
419				lines = append(lines, fmt.Sprintf("%s:%d: %s", m.Path, m.Line, m.Snippet))
420			}
421			textContent += ":\n" + strings.Join(lines, "\n")
422		}
423	
424		result := &mcp.CallToolResult{
425			Content: []mcp.Content{
426				&mcp.TextContent{Text: textContent},
427			},
428		}
429		return result, output, nil
430	}
431	
432	// GetBacklinks implements the get_backlinks tool
433	func (h *Handler) GetBacklinks(ctx context.Context, req *mcp.CallToolRequest, input note.GetBacklinksInput) (*mcp.CallToolResult, note.GetBacklinksOutput, error) {
434		if input.NoteName == "" {
435			return nil, note.GetBacklinksOutput{}, fmt.Errorf("note_name is required")
436		}
437	
438		noteName := strings.TrimSuffix(input.NoteName, ".md")
439		wikilinkRe := regexp.MustCompile(`\[\[([^\]|]+)(?:\|[^\]]+)?\]\]`)
440	
441		var results []note.Backlink
442	
443		err := filepath.Walk(h.vault.Path, func(path string, info os.FileInfo, err error) error {
444			if ctx.Err() != nil {
445				return ctx.Err()
446			}
447	
448			if err != nil {
449				h.logger.Debug("skipping path", "path", path, "error", err)
450				return nil
451			}
452	
453			if info.IsDir() {
454				allowed, checkErr := h.vault.IsPathAllowed(path)
455				if checkErr != nil || !allowed {
456					return filepath.SkipDir
457				}
458				return nil
459			}
460	
461			if !strings.HasSuffix(strings.ToLower(path), ".md") {
462				return nil
463			}
464	
465			allowed, checkErr := h.vault.IsPathAllowed(path)
466			if checkErr != nil || !allowed {
467				return nil
468			}
469	
470			// Exclude the target note itself
471			baseName := strings.TrimSuffix(filepath.Base(path), ".md")
472			if strings.EqualFold(baseName, noteName) {
473				return nil
474			}
475	
476			data, err := os.ReadFile(path)
477			if err != nil {
478				h.logger.Debug("skipping unreadable file", "path", path, "error", err)
479				return nil
480			}
481	
482			lines := strings.SplitSeq(string(data), "\n")
483			for line := range lines {
484				matches := wikilinkRe.FindAllStringSubmatch(line, -1)
485				for _, match := range matches {
486					if len(match) >= 2 {
487						linkTarget := strings.TrimSuffix(match[1], ".md")
488						if strings.EqualFold(linkTarget, noteName) {
489							results = append(results, note.Backlink{
490								Path: path,
491								Line: line,
492							})
493							break // one match per line is enough
494						}
495					}
496				}
497			}
498	
499			return nil
500		})
501	
502		if err != nil {
503			return nil, note.GetBacklinksOutput{}, fmt.Errorf("failed to search backlinks: %w", err)
504		}
505	
506		output := note.GetBacklinksOutput{Results: results}
507	
508		textContent := fmt.Sprintf("Found %d backlinks to [[%s]]", len(results), noteName)
509		if len(results) > 0 {
510			var lines []string
511			for _, bl := range results {
512				lines = append(lines, fmt.Sprintf("%s: %s", bl.Path, bl.Line))
513			}
514			textContent += ":\n" + strings.Join(lines, "\n")
515		}
516	
517		result := &mcp.CallToolResult{
518			Content: []mcp.Content{
519				&mcp.TextContent{Text: textContent},
520			},
521		}
522		return result, output, nil
523	}
524	
525	// ListTags implements the list_tags tool
526	func (h *Handler) ListTags(ctx context.Context, req *mcp.CallToolRequest, input note.ListTagsInput) (*mcp.CallToolResult, note.ListTagsOutput, error) {
527		tagCounts := make(map[string]int)
528	
529		// Regex for inline #tags (not inside code blocks)
530		inlineTagRe := regexp.MustCompile(`(?:^|\s)#([a-zA-Z][a-zA-Z0-9_/-]*)`)
531	
532		err := filepath.Walk(h.vault.Path, func(path string, info os.FileInfo, err error) error {
533			if ctx.Err() != nil {
534				return ctx.Err()
535			}
536	
537			if err != nil {
538				h.logger.Debug("skipping path", "path", path, "error", err)
539				return nil
540			}
541	
542			if info.IsDir() {
543				allowed, checkErr := h.vault.IsPathAllowed(path)
544				if checkErr != nil || !allowed {
545					return filepath.SkipDir
546				}
547				return nil
548			}
549	
550			if !strings.HasSuffix(strings.ToLower(path), ".md") {
551				return nil
552			}
553	
554			allowed, checkErr := h.vault.IsPathAllowed(path)
555			if checkErr != nil || !allowed {
556				return nil
557			}
558	
559			data, err := os.ReadFile(path)
560			if err != nil {
561				h.logger.Debug("skipping unreadable file", "path", path, "error", err)
562				return nil
563			}
564	
565			content := string(data)
566	
567			// Parse frontmatter tags
568			if strings.HasPrefix(content, "---\n") {
569				endIdx := strings.Index(content[4:], "\n---\n")
570				if endIdx >= 0 {
571					frontmatter := content[4 : 4+endIdx]
572					note.ParseFrontmatterTags(frontmatter, tagCounts)
573				}
574			}
575	
576			// Parse inline #tags (skip code blocks)
577			lines := strings.Split(content, "\n")
578			inCodeBlock := false
579			for _, line := range lines {
580				if strings.HasPrefix(strings.TrimSpace(line), "```") {
581					inCodeBlock = !inCodeBlock
582					continue
583				}
584				if inCodeBlock {
585					continue
586				}
587				matches := inlineTagRe.FindAllStringSubmatch(line, -1)
588				for _, match := range matches {
589					if len(match) >= 2 {
590						tagCounts[match[1]]++
591					}
592				}
593			}
594	
595			return nil
596		})
597	
598		if err != nil {
599			return nil, note.ListTagsOutput{}, fmt.Errorf("failed to list tags: %w", err)
600		}
601	
602		// Filter by prefix and sort
603		var tags []note.TagCount
604		for tag, count := range tagCounts {
605			if input.Prefix == "" || strings.HasPrefix(tag, input.Prefix) {
606				tags = append(tags, note.TagCount{Tag: tag, Count: count})
607			}
608		}
609		sort.Slice(tags, func(i, j int) bool {
610			return tags[i].Tag < tags[j].Tag
611		})
612	
613		output := note.ListTagsOutput{Tags: tags}
614	
615		textContent := fmt.Sprintf("Found %d unique tags", len(tags))
616		if len(tags) > 0 {
617			var lines []string
618			for _, tc := range tags {
619				lines = append(lines, fmt.Sprintf("#%s (%d)", tc.Tag, tc.Count))
620			}
621			textContent += ":\n" + strings.Join(lines, "\n")
622		}
623	
624		result := &mcp.CallToolResult{
625			Content: []mcp.Content{
626				&mcp.TextContent{Text: textContent},
627			},
628		}
629		return result, output, nil
630	}
